SINA_SMART["embryo1-folding"] = {"lecture":"embryo1-folding","title":"Folding, somites and organogenesis","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"embryo1-folding:e0","text":"Mesoderm: skeleton, muscle, dermis, urogenital system, serous membranes, heart, blood, spleen, adrenal cortex.","topic":"Germ layer derivatives","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-folding:e1","text":"Somites: first segmentation; their number dates the embryo; ~42-44 pairs by week 5.","topic":"Somites","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-folding:e2","text":"Somites → axial skeleton, its muscles and dermis.","topic":"Somites","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-folding:e7","text":"Intraembryonic coelom → pericardial, pleural, peritoneal cavities.","topic":"Somites","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-folding:e3","text":"Folding (week 4): median plane (head, tail) and horizontal plane (lateral).","topic":"Folding of the embryo","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-folding:e4","text":"Head fold: heart and pericardial coelom ventral; septum transversum caudal to heart; foregut.","topic":"Folding of the embryo","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-folding:e5","text":"Tail fold: connecting stalk and allantois ventral; hindgut.","topic":"Folding of the embryo","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-folding:e6","text":"Lateral folds: body walls; midgut linked to yolk sac by vitelline duct.","topic":"Folding of the embryo","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-folding:e8","text":"Haematopoiesis: yolk sac 3-8 wk, liver 6 wk-birth, spleen 10-28 wk, marrow from 18 wk.","topic":"Haematopoiesis before and after birth","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-folding:e9","text":"Weeks 4-8 = organogenesis, most sensitive to teratogens (e.g. alcohol).","topic":"Weeks 4 to 8 and teratology","sec":4,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"ii7t86":"a","oiky7j":"a","edzjk2":"a","1n7kwgc":"a","14o25b3":"a","dbzwt9":"a","atnirx":"a","rmj1lw":"a","yzvfor":"a","1ys21bg":"a","m9wkcq":"a","1u19wgx":"a","6lfp0s":"a","189le5b":"a","ho6qbh":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"embryo1-folding:e0":{"s":0,"u":["Mesoderm: skeleton, muscle, dermis, urogenital system, serous membranes, heart, blood, spleen, adrenal cortex.","Mesoderm : muscles of the head, skeletal muscles, skeleton (ribs, vertebrae), dermis , connective tissue, the urogenital system (gonads, ducts, glands), visceral muscle and connective tissue, serous membranes (pleura, pericardium, peritoneum), the heart, blood and lymphatic cells , the spleen and the suprarenal cortex ."],"dp":[]},"embryo1-folding:e1":{"s":1,"u":["Somites: first segmentation; their number dates the embryo; ~42-44 pairs by week 5.","Their number is used to date the embryo : they appear in week 4 and reach about 42-44 pairs by the end of week 5 .","Paraxial mesoderm segments into somites , the first sign of segmentation ."],"dp":[]},"embryo1-folding:e2":{"s":1,"u":["Somites → axial skeleton, its muscles and dermis.","Somites give most of the axial skeleton , its musculature and the dermis of the skin."],"dp":[]},"embryo1-folding:e7":{"s":1,"u":["Intraembryonic coelom → pericardial, pleural, peritoneal cavities.","The intraembryonic coelom (body cavity) forms in the mesoderm lateral to them."],"dp":[]},"embryo1-folding:e3":{"s":2,"u":["Folding (week 4): median plane (head, tail) and horizontal plane (lateral).","In week 4 the flat trilaminar disc becomes a cylinder , by folding in the median plane (head and tail folds) and the horizontal plane (lateral folds)."],"dp":[]},"embryo1-folding:e4":{"s":2,"u":["Head fold: heart and pericardial coelom ventral; septum transversum caudal to heart; foregut.","Head fold : the primordial heart, pericardial coelom and oropharyngeal membrane move to the ventral surface; part of the umbilical vesicle is incorporated as the foregut ; the septum transversum comes to lie caudal to the heart."],"dp":[{"h":"Why the heart ends up in the chest","t":"Before folding, the heart-forming (cardiogenic) mesoderm lies cranial to the oropharyngeal membrane and the neural plate, at the very front of the disc. As the brain grows rapidly and the head fold swings the cranial end under, the heart and pericardial cavity rotate 180° to lie ventral to the foregut, with the septum transversum now below them. That septum later forms part of the diaphragm, which is why the phrenic nerve comes from the neck (C3-C5): the diaphragm's tissue began life at cervical levels and descended with folding. Source: the lecture's fate of the head fold; the link to the phrenic nerve from Anatomy."}]},"embryo1-folding:e5":{"s":2,"u":["Tail fold: connecting stalk and allantois ventral; hindgut.","Tail fold : the primitive streak, first cranial to the cloacal membrane, ends up caudal; part of the endoderm forms the hindgut ; the connecting stalk and allantois move ventrally.","In week 4 the flat trilaminar disc becomes a cylinder , by folding in the median plane (head and tail folds) and the horizontal plane (lateral folds)."],"dp":[]},"embryo1-folding:e6":{"s":2,"u":["Lateral folds: body walls; midgut linked to yolk sac by vitelline duct.","Lateral folds : form the abdominal walls and the midgut , which communicates with the umbilical vesicle through the omphaloenteric (vitelline) duct ; the connection between intra- and extraembryonic coelom narrows; the amniotic cavity expands to surround the embryo."],"dp":[]},"embryo1-folding:e8":{"s":3,"u":["Haematopoiesis: yolk sac 3-8 wk, liver 6 wk-birth, spleen 10-28 wk, marrow from 18 wk.","Blood formation moves from site to site: yolk sac weeks 3-8, liver from week 6 until birth, spleen weeks 10-28, bone marrow from week 18 onwards.","Until about age 5 all marrow is active; afterwards mainly the marrow of the flat bones and axial skeleton."],"dp":[]},"embryo1-folding:e9":{"s":4,"u":["Weeks 4-8 = organogenesis, most sensitive to teratogens (e.g. alcohol).","A teratogen is any agent (viral, bacterial, chemical, environmental) that causes abnormal development; the embryonic period (organogenesis) is the most sensitive.","Examples: alcohol (fetal alcohol syndrome: cognitive deficits, heart damage, growth retardation, microcephaly), aspirin (deficits in attention and motor skills), caffeine (lower birth weight), cocaine and heroin (growth retardation, newborn irritability)."],"dp":[]}},"meta":{"ii7t86":{"a":"recall","vg":"embryo1-folding:e1/recall/1"},"oiky7j":{"a":"recall","vg":"embryo1-folding:e1/recall/2"},"edzjk2":{"a":"recall","vg":"embryo1-folding:e2/recall/1"},"1n7kwgc":{"a":"recall","vg":"embryo1-folding:e0/recall/1"},"14o25b3":{"a":"recall","vg":"embryo1-folding:e4/recall/1"},"dbzwt9":{"a":"recall","vg":"embryo1-folding:e5/recall/1"},"atnirx":{"a":"recall","vg":"embryo1-folding:e6/recall/1"},"rmj1lw":{"a":"recall","vg":"embryo1-folding:e7/recall/1"},"yzvfor":{"a":"recall","vg":"embryo1-folding:e8/recall/1"},"1ys21bg":{"a":"recall","vg":"embryo1-folding:e8/recall/2"},"m9wkcq":{"a":"recall","vg":"embryo1-folding:e1/recall/3"},"1u19wgx":{"a":"recall","vg":"embryo1-folding:e4/recall/2"},"6lfp0s":{"a":"recall","vg":"embryo1-folding:e9/recall/1"},"189le5b":{"a":"recall","vg":"embryo1-folding:e9/recall/2"},"ho6qbh":{"a":"recall","vg":"embryo1-folding:e3/recall/1"}},"explRev":"80b049734f61"};
